Here's an example of a generic REST service wrapper class in C# that includes auth token handling:

```csharp
using System;
using System.Net.Http;
using System.Threading.Tasks;

public class RestServiceWrapper<T>
{
    private readonly string _apiUrl;
    private readonly string _authToken;

    public RestServiceWrapper(string apiUrl, string authToken)
    {
        _apiUrl = apiUrl;
        _authToken = authToken;
    }

    public async Task<T> GetAsync()
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);
            var response = await client.GetAsync(_apiUrl);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsAsync<T>();
        }
    }
}
```

To use this class, simply create an instance of it with your API URL and auth token:

```csharp
var service = new RestServiceWrapper<MyData>("https://example.com/api/data", "your_auth_token");
var data = await service.GetAsync();
```

