Here's a Go program that parses a struct in a Go source file and generates a Avro schema from it:

```go
package main

import (
	"fmt"
	"io/ioutil"
	"reflect"
	"strings"

	"github.com/apache/avro/avro"
)

func main() {
	sourceFile := "example.go"
	structName := "MyStruct"

	content, err := ioutil.ReadFile(sourceFile)
	if err != nil {
		fmt.Println("Error reading source file:", err)
		return
	}

	tokens := strings.Split(string(content), "\n")
	for _, token := range tokens {
		if strings.HasPrefix(token, "type") {
			parts := strings.SplitN(token, " ", 2)
			if len(parts) == 2 && parts[1] == structName {
				structDef := parts[0]
				break
			}
		}
	}

	if structDef == "" {
		fmt.Println("Could not find struct definition in source file.")
		return
	}

	structType := reflect.TypeOf((*reflect.Value)(nil).Interface().(*reflect.PtrValue)(nil).UnsafeAddr())
	if structType.Kind() != reflect.Ptr {
		fmt.Println("Struct must be a pointer type.")
		return
	}

	structValue := reflect.New(structType).Interface()
	fields := reflect.StructTagNames(structValue.(reflect.Struct))

	schema := avro.Schema{
		Name:     structName,
		Fields:   make([]avro.Field, len(fields)),
		Default: "null",
	}

	for i, field := range fields {
		fieldType := reflect.TypeOf(structValue.(reflect.Struct).FieldByName(field)).String()
		fieldSchema := avro.Field{
			Name:     field,
			Type:     fieldType,
		}

